import {SimpleListView} from '@github-ui/simple-list-view'
import {SimpleListItem} from '@github-ui/simple-list-view/SimpleListItem'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {Pagination} from '@primer/react'
import {useState} from 'react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {updateSearchParams} from '@github-ui/history'
import styles from './TeamsSettingsPage.module.css'

export interface TeamsSettingsPageProps {
  teams: Array<{
    id: string
    name: string
    url: string
    avatar_url: string
  }>
  currentPage: number
  perPage: number
  totalCount: number
}

export function TeamsSettingsPage({
  teams: initialTeams,
  currentPage: initialCurrentPage,
  perPage: perPage,
  totalCount: initialTotalCount,
}: TeamsSettingsPageProps) {
  const [teams, setTeams] = useState(initialTeams)
  const [currentPage, setCurrentPage] = useState(initialCurrentPage)
  const [totalCount, setTotalCount] = useState(initialTotalCount)
  const [searchParams, setSearchParams] = useState(
    () => new URLSearchParams(typeof window !== `undefined` ? window.location.search : ''),
  )

  const pageCount = Math.ceil(totalCount / perPage)

  const paginate = async (page: number): Promise<void> => {
    const newSearchParams = new URLSearchParams(searchParams)
    newSearchParams.set('page', page.toString())
    setSearchParams(newSearchParams)
    updateSearchParams(newSearchParams)

    const result = await verifiedFetchJSON(`${window.location.pathname}?${newSearchParams.toString()}`, {
      method: 'GET',
      headers: {Accept: 'application/json'},
    })
    const data = await result.json()

    setCurrentPage(data.currentPage)
    setTeams(data.teams)
    setTotalCount(data.totalCount)
  }

  return (
    <>
      <SimpleListView>
        <SimpleListView.Items>
          {teams.map(team => (
            <SimpleListItem key={team.id}>
              <div className={styles.team}>
                <SimpleListItem.LeadingVisual>
                  <GitHubAvatar square src={team.avatar_url} />
                </SimpleListItem.LeadingVisual>
                <SimpleListItem.Title href={team.url}>{team.name}</SimpleListItem.Title>
              </div>
            </SimpleListItem>
          ))}
        </SimpleListView.Items>
      </SimpleListView>
      {pageCount > 1 && (
        <Pagination pageCount={pageCount} currentPage={currentPage} onPageChange={(_, newPage) => paginate(newPage)} />
      )}
    </>
  )
}
